// Extract Session Text
// Expects input from: Extract From File (Text) node
// $json.data contains the plain text string when Extract From File runs correctly.
// Falls back through binary decode and raw JSON for resilience.

const item = $input.first();
let rawText = '';
let extractionMethod = '';

// Path 1 — Extract From File node ran correctly (recommended setup)
// Text lands in $json.data as a plain string
if (typeof item.json?.data === 'string' && item.json.data.trim().length > 0) {
  rawText = item.json.data;
  extractionMethod = 'json.data (Extract From File)';
}

// Path 2 — Binary data still present (Extract From File skipped or misconfigured)
// Drive downloads .md as binary under field name 'data'
else if (item.binary?.data?.data) {
  rawText = Buffer.from(item.binary.data.data, 'base64').toString('utf-8');
  extractionMethod = 'binary.data.data (base64 decode)';
}

// Path 3 — Binary present under a different field name
// Check all binary fields and use the first one with content
else if (item.binary && Object.keys(item.binary).length > 0) {
  const binaryField = Object.keys(item.binary)[0];
  const binaryData = item.binary[binaryField];
  if (binaryData?.data) {
    rawText = Buffer.from(binaryData.data, 'base64').toString('utf-8');
    extractionMethod = `binary.${binaryField} (base64 decode, field auto-detected)`;
  }
}

// Path 4 — Text arrived directly as a JSON string (edge case)
else if (typeof item.json === 'string') {
  rawText = item.json;
  extractionMethod = 'raw json string';
}

// Log which path was used — visible in N8N execution output
console.log(`[Extract Session Text] Method: ${extractionMethod}`);
console.log(`[Extract Session Text] Raw text length: ${rawText.length} chars`);

// Trim and validate
rawText = rawText.trim();

if (!rawText || rawText.length < 50) {
  console.log('[Extract Session Text] DEBUG item.json keys:', Object.keys(item.json ?? {}));
  console.log('[Extract Session Text] DEBUG item.binary keys:', Object.keys(item.binary ?? {}));
  throw new Error(
    `Session file appears empty or too short (${rawText.length} chars). ` +
    `Extraction method attempted: ${extractionMethod || 'none — all paths failed'}. ` +
    `File ID: ${item.json?.id ?? item.json?.fileId ?? 'unknown'}. ` +
    `Check that Extract From File node is placed before this node and ` +
    `its Input Binary Field is set to "data".`
  );
}

// Parse structure from Granola Markdown
// Granola uses the meeting title as the first H1 line
const lines = rawText.split('\n').filter(l => l.trim().length > 0);
const title = lines[0].replace(/^#+\s*/, '').trim() || 'Untitled Session';

// Body lines: skip headings for the topic snippet
const bodyLines = lines.slice(1).filter(l => !l.startsWith('#') && l.trim().length > 10);
const topicSnippet = bodyLines.slice(0, 5).join(' ').substring(0, 600).trim();

// Extract any attendees Granola lists (usually "Attendees: Name, Name")
const attendeesLine = lines.find(l => /attendees?:/i.test(l)) ?? '';
const attendees = attendeesLine.replace(/attendees?:\s*/i, '').trim();

// Extract date from Granola header if present (format: "Mon 12 May 2025" or ISO)
const dateLine = lines.find(l => /\d{4}-\d{2}-\d{2}|\d{1,2}\s+\w+\s+\d{4}/.test(l)) ?? '';
const sessionDate = dateLine.trim() || new Date().toISOString();

console.log(`[Extract Session Text] Title: "${title}"`);
console.log(`[Extract Session Text] Topic snippet (first 100 chars): "${topicSnippet.substring(0, 100)}"`);

return [{
  json: {
    sessionTitle: title,
    sessionText: rawText,
    topicSnippet: topicSnippet,
    attendees: attendees,
    sessionDate: sessionDate,
    fileId: item.json?.id ?? item.json?.fileId ?? '',
    fileName: item.json?.name ?? title,
    charCount: rawText.length,
    extractionMethod: extractionMethod
  }
}];

// Parse Topic JSON
// Receives output from: Identify Best LinkedIn Topic (Agent node)
// Agent node returns output as $json.output (string)

let raw = '';

try {
  const item = $input.first();

  // Agent node output paths — try each in order
  if (typeof item?.json?.output === 'string') {
    raw = item.json.output;
  } else if (typeof item?.json?.output === 'object' && item?.json?.output !== null) {
    raw = JSON.stringify(item.json.output);
  } else if (typeof item?.json?.text === 'string') {
    raw = item.json.text;
  } else {
    // Last resort — stringify the whole json to see what arrived
    raw = JSON.stringify(item?.json ?? {});
  }
} catch (e) {
  throw new Error('Parse Topic JSON — could not read input: ' + e.message);
}

// Log raw output for debugging in N8N execution view
console.log('[Parse Topic] Raw output length:', raw.length);
console.log('[Parse Topic] Raw output preview:', raw.substring(0, 300));

// Strip markdown code fences if present (```json ... ```)
const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

// Find the JSON object — handles cases where agent adds text before/after
const jsonMatch = cleaned.match(/\{[\s\S]*\}/);

let parsed = null;

if (jsonMatch) {
  try {
    parsed = JSON.parse(jsonMatch[0]);
  } catch (e) {
    console.log('[Parse Topic] JSON.parse failed:', e.message);
    console.log('[Parse Topic] Attempted to parse:', jsonMatch[0].substring(0, 300));
    parsed = null;
  }
}

// Fallback: build a safe object from whatever the agent returned
if (!parsed || typeof parsed !== 'object') {
  console.log('[Parse Topic] Using fallback — could not parse JSON from agent output');
  parsed = {
    topic: raw.substring(0, 120).trim() || 'Coaching session insight',
    angle: 'Drawn from real coaching experience',
    targetEmotion: 'recognition',
    searchQuery: 'startup founder leadership Germany DACH',
    whyNow: 'Based on recent coaching session'
  };
}

// Sanitise each field — guarantee strings, never undefined
const sanitize = (val, fallback) => 
  (typeof val === 'string' && val.trim().length > 3) ? val.trim() : fallback;

return [{
  json: {
    topic:         sanitize(parsed.topic,         'Coaching session insight'),
    angle:         sanitize(parsed.angle,          'Drawn from real coaching experience'),
    targetEmotion: sanitize(parsed.targetEmotion,  'recognition'),
    searchQuery:   sanitize(parsed.searchQuery,    'startup founder leadership Germany'),
    whyNow:        sanitize(parsed.whyNow,         'Relevant for founders right now'),
    rawOutput:     raw.substring(0, 500)
  }
}];

