// Guard — Empty Post Output
// Only reads from $input — no external node references in sandbox

let postText = '';

try {
  const item = $input.first();

  // Create LinkedIn Post (OpenAI node) returns output in different shapes
  // Try each path in order
  if (typeof item?.json?.output === 'string') {
    postText = item.json.output;
  } else if (Array.isArray(item?.json?.output)) {
    // OpenAI node: output[0].content[0].text
    postText = item?.json?.output?.[0]?.content?.[0]?.text ?? '';
  } else if (typeof item?.json?.text === 'string') {
    postText = item.json.text;
  } else if (typeof item?.json?.message?.content === 'string') {
    postText = item.json.message.content;
  }
} catch (e) {
  throw new Error('Guard — could not read input from Create LinkedIn Post: ' + e.message);
}

postText = postText.trim();

console.log('[Guard] Post text length:', postText.length);
console.log('[Guard] Post preview:', postText.substring(0, 150));

if (!postText || postText.length < 30) {
  throw new Error(
    'LinkedIn post is empty or too short (' + postText.length + ' chars). ' +
    'Check the Create LinkedIn Post node output in the execution log.'
  );
}

return [{
  json: {
    postText: postText
  }
}];

